#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {   //@ @layout open:container
    vector<int> a = {3, 1, 2};   //@ @tts [next] 準備一個陣列
    int i = 0;   //@ @tts [next] 先指向第零格
    int j = 1;   //@ @tts [next] 另一個指向第一格
    swap(a[i], a[j]);   //@ @guide {a[i]:orange} {a[j]:lightblue} @tts [next] 把這兩格交換
    j = 2;   //@ @guide {a} @tts [next] 第二次，換成跟第二格交換
    swap(a[i], a[j]);   //@ @guide {a[i]:orange} {a[j]:lightblue} @tts [next] 再交換一次
    cout << a[0] << endl;   //@ @guide {a} @tts [next] 最小的跑到最前面了
    return 0;   //@ @tts [continue] 程式結束
}
